def compute(vars):
    revenues = [vars["v1"], vars["v2"], vars["v3"]]
    threshold = 1000000
    count_exceeding = sum(1 for revenue in revenues if revenue > threshold)

    return {
        "value": count_exceeding,
        "trace": {
            "revenues": revenues,
            "threshold": threshold,
            "count_exceeding": count_exceeding,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "count"
            }
        }
    }
